def norm360(a):
    return a % 360.0


def jd_ut(y, m, d, h=0.0):
    if m <= 2:
        y -= 1
        m += 12
    A = y // 100
    B = 2 - A + A // 4
    return math.floor(365.25 * (y + 4716)) + math.floor(30.6001 * (m + 1)) + d + B - 1524.5 + h / 24


def ymd(J):
    z = math.floor(J + 0.5)
    a = math.floor((z - 1867216.25) / 36524.25)
    b = z + 1 + a - a // 4 + 1524
    c = math.floor((b - 122.1) / 365.25)
    d = math.floor(365.25 * c)
    e = math.floor((b - d) / 30.6001)
    day = b - d - math.floor(30.6001 * e)
    m = e - 1 if e < 14 else e - 13
    return (c - 4716 if m > 2 else c - 4715), m, day


def vec(ra, dec):
    return [math.cos(dec * DEG) * math.cos(ra * DEG), math.cos(dec * DEG) * math.sin(ra * DEG), math.sin(dec * DEG)]


def dot(a, b):
    return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]


def cross(a, b):
    return [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]]


def unit(v):
    n = math.sqrt(dot(v, v))
    return [x / n for x in v]


def mv(M, v):
    return [M[0][0] * v[0] + M[0][1] * v[1] + M[0][2] * v[2], M[1][0] * v[0] + M[1][1] * v[1] + M[1][2] * v[2], M[2][0] * v[0] + M[2][1] * v[1] + M[2][2] * v[2]]


def clamp(x, a, b):
    return max(a, min(b, x))


def hvec(alt, az):
    return [math.sin(az * DEG) * math.cos(alt * DEG), math.cos(az * DEG) * math.cos(alt * DEG), math.sin(alt * DEG)]


EPS = 23.4393 * DEG
ECL = [[1, 0, 0], [0, math.cos(EPS), math.sin(EPS)], [0, -math.sin(EPS), math.cos(EPS)]]


def ecl2eq(v):
    return [v[0], v[1] * math.cos(EPS) - v[2] * math.sin(EPS), v[1] * math.sin(EPS) + v[2] * math.cos(EPS)]


ELEM = {"earth": [1.00000261, 0.00000562, 0.01671123, -0.00004392, -0.00001531, -0.01294668, 100.46457166, 35999.37244981, 102.93768193, 0.32327364, 0, 0],
        "mars": [1.52371034, 0.00001847, 0.09339410, 0.00007882, 1.84969142, -0.00813131, -4.55343205, 19140.30268499, -23.94362959, 0.44441088, 49.55953891, -0.29257343]}


def helio(p, J):
    Tc = (J - 2451545) / 36525
    E0 = ELEM[p]

    def el(i):
        return E0[2 * i] + E0[2 * i + 1] * Tc
    a, e, I, L, w, O = el(0), el(1), el(2) * DEG, el(3), el(4), el(5)
    om, M = (w - O) * DEG, norm360(L - w) * DEG
    E = M + e * math.sin(M)
    for _ in range(8):
        E -= (E - e * math.sin(E) - M) / (1 - e * math.cos(E))
    xp, yp = a * (math.cos(E) - e), a * math.sqrt(1 - e * e) * math.sin(E)
    Or = O * DEG
    co, so, cO, sO, cI, sI = math.cos(om), math.sin(om), math.cos(Or), math.sin(Or), math.cos(I), math.sin(I)
    return [(co * cO - so * sO * cI) * xp + (-so * cO - co * sO * cI) * yp, (co * sO + so * cO * cI) * xp + (-so * sO + co * cO * cI) * yp, so * sI * xp + co * sI * yp]


def mars_geo(J):
    e = helio("earth", J)
    Jt, g = J, None
    for _ in range(2):
        h = helio("mars", Jt)
        g = [h[i] - e[i] for i in range(3)]
        Jt = J - math.sqrt(dot(g, g)) * 0.0057755
    return ecl2eq(g), ecl2eq([-x for x in e])


def lam_bet(e):
    return norm360(math.atan2(e[1], e[0]) / DEG), math.asin(clamp(e[2] / math.sqrt(dot(e, e)), -1, 1)) / DEG


def ecl_vec(lam, bet):
    return [math.cos(bet * DEG) * math.cos(lam * DEG), math.cos(bet * DEG) * math.sin(lam * DEG), math.sin(bet * DEG)]


