def _stars5():
    out = [list(s) for s in STARS]
    for _, ra, de, _, _, m, _, bv in VARS:
        v = vec(ra, de)
        hit = None
        for s in out:
            if dot(s[0], v) > math.cos(0.08 * DEG):
                hit = s
                break
        if hit:
            hit[1] = m
        else:
            out.append([v, m, bv])
    return out


