BORD = ["Cet", "Cae", "Pup", "Crt", "Mus", "Ser", "CrA", "Equ"]


def _bounds():
    out = []
    for c in BORD:
        rings = list(BOUNDS[c]) + ([SER_CAPUT] if c == "Ser" else [])
        for r in rings:
            pts = []
            for i in range(len(r) - 1):
                (a0, d0), (a1, d1) = r[i], r[i + 1]
                da = (a1 - a0 + 540) % 360 - 180
                n = max(1, int(math.ceil(max(abs(da), abs(d1 - d0)))))
                for k in range(n):
                    pts.append(vec(a0 + da * k / n, d0 + (d1 - d0) * k / n))
            pts.append(pts[0])
            c0 = [0.0, 0.0, 0.0]
            for ra, de in r:
                c0 = [x + y for x, y in zip(c0, vec(ra, de))]
            out.append((c, pts, unit(c0)))
    return out


