def _meteors():
    rnd = random.Random(2023)
    out = []
    for k in range(52):
        sporadic = k % 13 == 7
        R = unit([rnd.random() - 0.5, rnd.random() - 0.5, rnd.random() - 0.5]) if sporadic else RAD5
        e1 = unit(cross(R, [0, 0, 1]))
        e2 = cross(R, e1)
        out.append({"t": 2 + rnd.random() * 116, "R": R, "b": (e1, e2), "pa": rnd.random() * 2 * math.pi, "d0": (8 + rnd.random() * 50) * DEG,
                    "len": (4 + rnd.random() * 12) * DEG, "dur": 0.35 + rnd.random() * 0.6, "m": -1 + rnd.random() * 4})
    return out


