J06, DAYS6, LEAD = jd_ut(1915, 3, 1), 548, 20.0


def day6(tau):
    return clamp(tau - LEAD, 0, DAYS6)


def mars6(J):
    g, s = mars_geo(J)
    h = [g[i] - s[i] for i in range(3)]
    D, r = math.sqrt(dot(g, g)), math.sqrt(dot(h, h))
    alpha = math.acos(clamp(dot(g, h) / D / r, -1, 1)) / DEG
    e = mv(ECL, unit(g))
    lam, bet = lam_bet(e)
    sl = lam_bet(mv(ECL, s))[0]
    return {"e": e, "lam": lam, "bet": bet, "elong": (lam - sl + 540) % 360 - 180, "mag": -1.52 + 5 * math.log10(r * D) + 0.016 * alpha}


def _path6():
    out = [mars6(J06 + k / 4) for k in range(DAYS6 * 4 + 1)]
    off = 0.0
    out[0]["lu"] = out[0]["lam"]
    for k in range(1, len(out)):
        d = out[k]["lam"] - out[k - 1]["lam"]
        if d > 180:
            off -= 360
        if d < -180:
            off += 360
        out[k]["lu"] = out[k]["lam"] + off
    return out


PATH6 = _path6()


def _events6():
    ev = {}
    for k in range(1, len(PATH6)):
        a, b = PATH6[k - 1], PATH6[k]
        if k > 1:
            d0, d1 = a["lu"] - PATH6[k - 2]["lu"], b["lu"] - a["lu"]
            if (d0 < 0) != (d1 < 0):
                ev["s2" if "s1" in ev else "s1"] = J06 + (k - 1) / 4
        for t, key in ((-90, "q1"), (90, "q2"), (180, "opp")):
            x, y = (a["elong"] - t + 540) % 360 - 180, (b["elong"] - t + 540) % 360 - 180
            if x * y <= 0 and abs(x - y) < 20 and key not in ev:
                f = x / (x - y)
                ev[key] = J06 + (k - 1 + f) / 4
                if key == "opp":
                    ev["beta"] = a["bet"] + (b["bet"] - a["bet"]) * f
    ev["width"] = abs(PATH6[round((ev["s1"] - J06) * 4)]["lu"] - PATH6[round((ev["s2"] - J06) * 4)]["lu"])
    return ev


