PL7 = {"b": [36.261, 1.116], "c": [58.123, 1.097], "d": [97.191, 0.788], "e": [146.392, 0.920], "f": [220.961, 1.045], "g": [296.471, 1.129], "h": [450.55, 0.755]}
for _k in PL7:
    PL7[_k].append((PL7[_k][0] / PL7["f"][0]) ** (2 / 3))
TAU_KM = 0.03849 * 1.495979e8
RSTAR, RE_TAU = 0.1192 * 695700 / TAU_KM, 6371 / TAU_KM
SDIR = vec(346.622 + 180, 5.041)
_np = vec(0, 90)
NPOLE = unit([_np[i] - dot(_np, SDIR) * SDIR[i] for i in range(3)])
YDIR = cross(NPOLE, SDIR)
LAM0 = {"f": 40.0, "g": 205.0, "h": 310.0}
for _k, _t in (("b", 9), ("c", 23), ("d", 61), ("e", 41)):
    LAM0[_k] = 40 - 360 * _t / (1 / (1 / PL7[_k][0] - 1 / PL7["f"][0]))
SUN7 = vec(166.622, 5.041)
KEY7 = {}
for _k in "bcde":
    _P, _, _a = PL7[_k]
    KEY7[_k] = {"P": _P, "a": _a, "S": 1 / (1 / _P - 1 / PL7["f"][0]), "el": math.asin(_a) / DEG}


def hours7(tau):
    return clamp(tau - LEAD, 0, 520)


def pos7(k, t):
    P, _, a = PL7[k]
    l = (LAM0[k] + 360 * t / P) * DEG
    return [a * (math.cos(l) * SDIR[i] + math.sin(l) * YDIR[i]) for i in range(3)]


def bodies7(t):
    rf = pos7("f", t)
    e1 = unit([-x for x in rf])
    e2 = cross(NPOLE, e1)
    z = [math.cos(20 * DEG) * e1[i] + math.sin(20 * DEG) * e2[i] for i in range(3)]
    R = [cross(NPOLE, z), NPOLE, z]
    out = []
    for k in "bcdegh":
        p = pos7(k, t)
        d = [p[i] - rf[i] for i in range(3)]
        D, r = math.sqrt(dot(d, d)), math.sqrt(dot(p, p))
        alpha = math.acos(clamp(dot(p, d) / r / D, -1, 1))
        ph = (math.sin(alpha) + (math.pi - alpha) * math.cos(alpha)) / math.pi
        out.append({"k": k, "v": unit(d), "D": D, "alpha": alpha, "ang": PL7[k][1] * RE_TAU / D,
                    "mag": -4 - 2.5 * math.log10(PL7[k][1] ** 2 * max(1e-4, ph) / (r * r * D * D))})
    return R, e1, out


