def nums(s):
    return [float(x.replace(",", ".")) for x in re.findall(r"-?\d+(?:[.,]\d+)?", str(s or "").replace("−", "-").replace("–", "-"))]


def num(s):
    n = nums(s)
    return n[0] if n else None


def mk(v):
    return "" if v is None else (" ✓" if v else " ✗")


def within(s, lo, hi):
    v = num(s)
    return None if v is None else lo <= v <= hi


def hours_of(s):
    m = re.search(r"(\d+(?:\.\d+)?)\s*(?:h|:|시)\s*(\d+(?:\.\d+)?)?", str(s or "").lower())
    return float(m.group(1)) + (float(m.group(2)) / 60 if m.group(2) else 0) if m else num(s)


MONW = {"jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6, "jul": 7, "aug": 8, "sep": 9, "oct": 10, "nov": 11, "dec": 12}


def date_of(s):
    s = str(s or "").strip().lower()
    if not s:
        return None
    m = None
    w = re.search(r"[a-z]{3}", s)
    if w and w.group(0) in MONW:
        m = MONW[w.group(0)]
    n = [int(x) for x in re.findall(r"\d+", s)]
    y = None
    for x in n:
        if x > 1800:
            y = x
    rest = [x for x in n if x <= 1800]
    d = None
    if m:
        d = rest[0] if rest else None
    elif re.match(r"^\d{4}", s) or "월" in s or "/" in s:
        m, d = (rest + [None, None])[:2]
    else:
        d, m = (rest + [None, None])[:2]
    if not m or not d or m > 12 or d > 31:
        return None
    if y:
        return jd_ut(y, m, d)
    # without a year: the one nearer the opposition, as every event asked for lies within a few months of it
    return min((jd_ut(yy, m, d) for yy in (1915, 1916)), key=lambda J: abs(J - EV6["opp"]))


def d_ok(s, *Js):
    J = date_of(s)
    if J is None:
        return False if s else None
    return any(abs(J - x) <= 5.5 for x in Js)


