def bv_rgb(bv):
    t = clamp(bv, -0.4, 2.4)
    if t < 0.4:
        r, g, b = 0.72 + 0.7 * (t + 0.4), 0.8 + 0.4 * (t + 0.4), 1.0
    else:
        r, g, b = 1.0, 1.05 - 0.28 * (t - 0.4), 1 - 0.45 * (t - 0.4)
    return min(1, r), min(1, g), clamp(b, 0.35, 1)


def hexc(r, g, b):
    return "#%02x%02x%02x" % (int(clamp(r, 0, 255)), int(clamp(g, 0, 255)), int(clamp(b, 0, 255)))


